"""
Udev rule generation for lab serial devices.

Generates and installs udev rules from the serial_devices database table,
creating /dev/lab/<name> symlinks for registered USB-serial adapters.
"""

import re
import subprocess
from pathlib import Path
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from labctl.core.models import SerialDevice

UDEV_RULES_PATH = Path("/etc/udev/rules.d/99-lab-serial.rules")

UDEV_HEADER = """\
# Lab Controller Serial Device Rules
# Auto-generated by labctl - do not edit manually
# Regenerate with: labctl serial udev --install
#
# Devices are root:dialout 0660: the labctl services (in dialout) and
# ser2net (root) open them; users outside dialout reach consoles through
# ser2net, but can't drive relays or use `labctl console --direct`.
"""


def generate_udev_rules(devices: list["SerialDevice"]) -> str:
    """Generate udev rules text from a list of serial devices."""
    lines = [UDEV_HEADER]

    for dev in sorted(devices, key=lambda d: d.name):
        comment_parts = []
        if dev.vendor:
            comment_parts.append(dev.vendor)
        if dev.model:
            comment_parts.append(dev.model)
        comment = f" ({', '.join(comment_parts)})" if comment_parts else ""

        lines.append(f"# {dev.name}{comment}")
        lines.append(
            f'SUBSYSTEM=="tty", KERNELS=="{dev.usb_path}", '
            f'SYMLINK+="lab/{dev.name}", GROUP="dialout", MODE="0660"'
        )
        lines.append("")

    return "\n".join(lines)


_RULE_SYMLINK_RE = re.compile(r'SYMLINK\+?="([^"]*)"')
_RULE_KERNELS_RE = re.compile(r'KERNELS=="([^"]*)"')


def rule_links(rules_text: str) -> dict[str, str | None]:
    """The ``/dev/lab/<name>`` links a rules file creates: name -> USB path
    (KERNELS), or None when the rule's USB path can't be parsed. Every
    ``SYMLINK`` / ``SYMLINK+`` value naming ``lab/<name>`` counts, in any
    attribute order and among other link names."""
    links: dict[str, str | None] = {}
    for line in rules_text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        names = [
            link[len("lab/") :]
            for value in _RULE_SYMLINK_RE.findall(line)
            for link in value.split()
            if link.startswith("lab/") and len(link) > len("lab/")
        ]
        if not names:
            continue
        kernels = _RULE_KERNELS_RE.search(line)
        for name in names:
            links[name] = kernels.group(1) if kernels else None
    return links


def installed_rule_links(
    rules_path: Path | None = None,
) -> dict[str, str | None] | None:
    """The links the installed rules file creates ({} when there is none
    yet), or None when it exists but can't be read."""
    try:
        return rule_links((rules_path or UDEV_RULES_PATH).read_text())
    except FileNotFoundError:
        return {}
    except (OSError, UnicodeDecodeError):
        return None


def changed_links(old: dict[str, str | None], new: dict[str, str]) -> set[str]:
    """Link names that installing ``new`` over ``old`` removes or points
    at a different USB path; an old link whose USB path couldn't be
    parsed (None) counts as changed. New names only add links, so they're
    not included."""
    return {name for name, usb_path in old.items() if new.get(name) != usb_path}


def device_group_note(group: str = "dialout") -> str | None:
    """What the user running labctl must do to open the root:<group> 0660
    devices the rules create, or None when nothing. Under sudo that is the
    invoking user (SUDO_USER), not root; plain root needs nothing, nor does
    a system without ``group``."""
    import grp
    import os
    import pwd

    try:
        entry = grp.getgrnam(group)
    except KeyError:
        return None
    gid = entry.gr_gid
    sudo_user = os.environ.get("SUDO_USER") if os.geteuid() == 0 else None
    if os.geteuid() == 0 and sudo_user in (None, "root"):
        return None
    if sudo_user is None:
        if gid == os.getegid() or gid in os.getgroups():
            return None
        try:
            account = pwd.getpwuid(os.geteuid())
        except KeyError:
            return None
        user, primary_gid = account.pw_name, account.pw_gid
    else:
        try:
            user, primary_gid = sudo_user, pwd.getpwnam(sudo_user).pw_gid
        except KeyError:
            return None
    member = user in entry.gr_mem or primary_gid == gid
    if member and sudo_user is not None:
        return None
    access = (
        f"the devices are root:{group} 0660, so you can't open them directly "
        f"(relays from the CLI, `labctl console --direct`) until "
    )
    if member:
        return access + (
            f"you log in again: {user} was added to {group} after this "
            f"session started"
        )
    return access + (
        f"{user} joins {group}: sudo usermod -aG {group} {user} (then log in " f"again)"
    )


def install_udev_rules(
    rules_text: str,
    rules_path: Path = UDEV_RULES_PATH,
) -> None:
    """Write udev rules to the system rules directory.

    Raises PermissionError if unable to write.
    """
    rules_path.write_text(rules_text)


def reload_udev() -> bool:
    """Reload udev rules and trigger device re-evaluation.

    Tries direct execution first, falls back to sudo if permission denied.
    Returns True on success.
    """
    for use_sudo in (False, True):
        try:
            prefix = ["sudo"] if use_sudo else []
            subprocess.run(
                [*prefix, "udevadm", "control", "--reload-rules"],
                check=True,
                capture_output=True,
            )
            subprocess.run(
                [*prefix, "udevadm", "trigger", "--subsystem-match=tty"],
                check=True,
                capture_output=True,
            )
            return True
        except subprocess.CalledProcessError:
            if not use_sudo:
                continue  # Retry with sudo
            return False
        except FileNotFoundError:
            return False
    return False


def discover_usb_serial() -> list[dict]:
    """Discover connected USB-serial devices by reading /sys.

    Returns a list of dicts with keys:
        device, path, usb_path, vendor, model, serial
    """
    devices = []
    tty_classes = [Path("/sys/class/tty")]

    for tty_dir in tty_classes:
        if not tty_dir.exists():
            continue
        for entry in sorted(tty_dir.iterdir()):
            name = entry.name
            if not (name.startswith("ttyUSB") or name.startswith("ttyACM")):
                continue

            device_link = entry / "device"
            if not device_link.exists():
                continue

            # Walk up to find the USB device path
            info = _get_udev_info(name)
            if info and info.get("usb_path"):
                devices.append(info)

    return devices


def _get_udev_info(tty_name: str) -> dict | None:
    """Get USB device info via udevadm."""
    try:
        result = subprocess.run(
            ["udevadm", "info", "--name", f"/dev/{tty_name}", "--attribute-walk"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if result.returncode != 0:
            return None

        usb_path = None
        vendor = None
        model = None
        serial = None

        # udevadm --attribute-walk starts at the device and walks UP
        # to the root. We want the first (most specific) match for each field.
        for line in result.stdout.splitlines():
            line = line.strip()
            if line.startswith('KERNELS=="') and not line.startswith('KERNELS=="tty'):
                val = line.split('"')[1]
                # USB device paths look like "1-10.1.3"
                # Skip: PCI paths (0000:), interface descriptors (contain :),
                # and bare hub paths (no dot = just "1-12")
                if (
                    val
                    and "-" in val
                    and ":" not in val
                    and "." in val
                    and not val.startswith("0000:")
                    and usb_path is None
                ):
                    usb_path = val
            elif line.startswith('ATTRS{manufacturer}=="') and vendor is None:
                vendor = line.split('"')[1]
            elif line.startswith('ATTRS{product}=="') and model is None:
                model = line.split('"')[1]
            elif line.startswith('ATTRS{serial}=="') and serial is None:
                serial = line.split('"')[1]

        if not usb_path:
            return None

        return {
            "device": tty_name,
            "path": f"/dev/{tty_name}",
            "usb_path": usb_path,
            "vendor": vendor or "",
            "model": model or "",
            "serial": serial or "",
        }
    except (subprocess.TimeoutExpired, FileNotFoundError):
        return None
